contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0));

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cBalanceAfter = address(c).balance;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            ownerAfter == ownerBefore &&
            (
                (reverted && cBalanceAfter == cBalanceBefore) ||
                (!reverted && cBalanceAfter == 0)
            )
        );
    }

    receive() external payable {}
}

