pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address recipient) internal {
        vm.assume(recipient != address(0));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 cBalanceAfter = address(c).balance;
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue(ownerAfter == ownerBefore &&
            (
                (reverted && cBalanceAfter == cBalanceBefore) ||
                (!reverted && cBalanceAfter == 0)
            ));
    }

